-- 610: the 1d-first run's data gate holds (ledger 2026-11-21g).
--
-- 1. infra.corpus_rerun.data_gate.held_name_years gains the 21 name-years of 12 illiquid names whose
--    1d sessions are zero-volume no-trade days (not archive holes); with the two POWI years of
--    migration 607 it holds 23 name-years of about 190,000 judged. Version 1 becomes 2.
-- 2. New key infra.corpus_rerun.data_gate.held_names: JSON list of {symbol, evidence}, names with no
--    proven start the gate holds instead of refusing (services/corpus_rerun_data_gate.py evaluate,
--    read through services/corpus_rerun_apr.py). Seeded with the 11 names whose session_coverage
--    verdicts d2_landed already holds (migration 609): vendor-side holes, 202 member months.
-- Both keys are in APR_KEYS and so join the apr_hash of every run created after this migration.
-- Idempotent; no table is rewritten, so no VACUUM clause is owed.

BEGIN;

UPDATE config_state
   SET config_value = '[{"symbol": "POWI", "year": 2006, "evidence": "Massive raw rows absent (300 rows for 2006-01 to 2008-01 against about 525 expected, none for Sep 2006), canonical equals raw, cause unverified; 70 of 251 judged sessions missing"}, {"symbol": "POWI", "year": 2007, "evidence": "Massive raw rows absent (none for Jan to Jul 2007), canonical equals raw, cause unverified; 153 of 251 judged sessions missing"}, {"symbol": "ADTX", "year": 2021, "evidence": "252 judged sessions, 116 missing a tradeable 1d bar; the 1d table holds 252 bars in the year, 136 with volume above zero and 116 with zero volume; raw massive/sip_flat; zero-volume no-trade days of an illiquid name, not archive holes (compute masks them: no_fill)"}, {"symbol": "ADTX", "year": 2023, "evidence": "250 judged sessions, 149 missing a tradeable 1d bar; the 1d table holds 250 bars in the year, 101 with volume above zero and 149 with zero volume; raw massive/sip_flat; zero-volume no-trade days of an illiquid name, not archive holes (compute masks them: no_fill)"}, {"symbol": "ADTX", "year": 2024, "evidence": "252 judged sessions, 13 missing a tradeable 1d bar; the 1d table holds 252 bars in the year, 239 with volume above zero and 13 with zero volume; raw massive/sip_flat; zero-volume no-trade days of an illiquid name, not archive holes (compute masks them: no_fill)"}, {"symbol": "CNSP", "year": 2021, "evidence": "86 judged sessions, 77 missing a tradeable 1d bar; the 1d table holds 252 bars in the year, 50 with volume above zero and 202 with zero volume; raw massive/sip_flat; zero-volume no-trade days of an illiquid name, not archive holes (compute masks them: no_fill)"}, {"symbol": "EZGO", "year": 2021, "evidence": "128 judged sessions, 86 missing a tradeable 1d bar; the 1d table holds 234 bars in the year, 93 with volume above zero and 141 with zero volume; raw massive/sip_flat; zero-volume no-trade days of an illiquid name, not archive holes (compute masks them: no_fill)"}, {"symbol": "EZ