INSERT INTO config_history (timestamp, config_key, version, config_value, changed_by, reason)
SELECT NOW(), config_key, 2, config_value, 'migration_610',
       'Hold the 21 zero-volume no-trade name-years of the 1d-first run (ledger 2026-11-21g)'
  FROM config_state
 WHERE config_key = 'infra.corpus_rerun.data_gate.held_name_years'
